67: const dialogueEl=document.querySelector('#dialogue');function openDialogue(npc){dialogueTarget=npc;document.querySelector('#speaker').textContent=npc.userData.name+(npc.userData.job==='elder'?' · Elder':npc.userData.job==='shepherd'?' · Shepherd':'');dialogueEl.classList.add('show');document.querySelector('#say').focus();let line=npc.userData.job==='elder'?"You’ve come along the Lanternroad, stranger. I am Mara. We’ve had little cause to welcome travelers lately—but you look like you know how to listen.":npc.userData.job==='shepherd'?"The ridge flocks are restless. Smoke on the south road, and no birds near the old watchpost. Bad signs, all of them.":"Warm bread, cold news. The raiders came by night. Took three from our village and left their own marks on the road.";if(phase>=1)line=npc.userData.job==='elder'?"The old watchpost, south beyond the standing stones. That’s where they’ve taken Seli, Orin and Dara. Please—bring them back.":"The camp is beyond the old stones, down the south track. Five guards, at least. Be careful, friend.";document.querySelector('#dialogueText').textContent=line;
